using System; using System.Data; using System.Data.SqlClient; namespace PlacementDashboard.Admin { public partial class ViewStudents : System.Web.UI.Page { protected void Page_Load(object sender,EventArgs e) { if(!IsPostBack) Bind(); } void Bind() { StudentsGrid.DataSource=PlacementDashboard.DBConnection.GetStudents(); StudentsGrid.DataBind(); } protected void Selected(object sender,EventArgs e) { int id=(int)StudentsGrid.SelectedDataKey.Value; var r=PlacementDashboard.DBConnection.GetStudents().Select("StudentId="+id); Details.DataSource=r; Details.DataBind(); StudentForm.DataSource=r; StudentForm.DataBind(); } protected void Delete(object sender,System.Web.UI.WebControls.GridViewDeleteEventArgs e) { int id=(int)StudentsGrid.DataKeys[e.RowIndex].Value; PlacementDashboard.DBConnection.Execute("DELETE FROM Students WHERE StudentId=@id",new SqlParameter("@id",id)); Bind(); } } }
